create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('registered','innovator','mentor','admin'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', role public.app_role not null default 'registered', country text not null default 'Nigeria', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.climate_activities (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, category text not null check(category in ('tree_planting','clean_up','waste_recycling','environmental_education','other')), country text not null default 'Nigeria', state text, activity_date date not null default current_date, participants integer not null default 1 check(participants>0), quantity numeric(12,2) check(quantity is null or quantity>=0), unit text, description text not null default '', verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected')), created_at timestamptz not null default now());
create table if not exists public.project_ideas (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, answers jsonb not null default '{}'::jsonb, status text not null default 'draft' check(status in ('draft','submitted','under_review','approved','rejected')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.climate_activities enable row level security; alter table public.project_ideas enable row level security;
drop policy if exists "Users can read their own profile" on public.profiles; create policy "Users can read their own profile" on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists "Users can update their own profile" on public.profiles; create policy "Users can update their own profile" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "Users can read their own activities" on public.climate_activities; create policy "Users can read their own activities" on public.climate_activities for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users can submit activities" on public.climate_activities; create policy "Users can submit activities" on public.climate_activities for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists "Users can update their pending activities" on public.climate_activities; create policy "Users can update their pending activities" on public.climate_activities for update to authenticated using(auth.uid()=user_id and verification_status='pending') with check(auth.uid()=user_id and verification_status='pending');
drop policy if exists "Users can delete their pending activities" on public.climate_activities; create policy "Users can delete their pending activities" on public.climate_activities for delete to authenticated using(auth.uid()=user_id and verification_status='pending');
drop policy if exists "Users can read their own projects" on public.project_ideas; create policy "Users can read their own projects" on public.project_ideas for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Users can create their own projects" on public.project_ideas; create policy "Users can create their own projects" on public.project_ideas for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists "Users can update their own projects" on public.project_ideas; create policy "Users can update their own projects" on public.project_ideas for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "Users can delete their own projects" on public.project_ideas; create policy "Users can delete their own projects" on public.project_ideas for delete to authenticated using(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
grant usage on schema public to authenticated; grant select,update on public.profiles to authenticated; grant select,insert,update,delete on public.climate_activities to authenticated; grant select,insert,update,delete on public.project_ideas to authenticated;
